 for(int i=0;i<4;i++){var root=new GameObject("Independent demolition bay "+(i+1)).transform;root.position=new Vector3(i*200,0,0);var b=root.gameObject.AddComponent<BungeeBay>();b.match=m;b.slot=i;b.towerPrefab=tower;b.towerMount=new GameObject("Tower foundation").transform;b.towerMount.SetParent(root,false);b.towerMount.localPosition=new Vector3(12,0,10);b.craneAnchor=new GameObject("Crane bungee anchor").transform;b.craneAnchor.SetParent(root,false);b.craneAnchor.localPosition=new Vector3(0,65,-12);b.truck=SportsEventAuthoring.Truck(m,Folder,"Suspended wrecking truck "+(i+1),root.position+new Vector3(-7,62,-22),i);b.truck.transform.SetParent(root,true);SportsRallyAuthoring.FitTruck(b.truck);b.truck.Power(false);b.truck.body.isKinematic=true;b.spring=b.truck.gameObject.AddComponent<SpringJoint>();b.spring.autoConfigureConnectedAnchor=false;b.spring.connectedAnchor=b.craneAnchor.position;b.spring.anchor=new Vector3(0,.5f,-.5f);b.spring.maxDistance=b.restLength;b.spring.minDistance=0;b.spring.spring=b.springStrength;b.spring.damper=b.damping;b.spring.tolerance=.05f;b.spring.enableCollision=false;b.spring.massScale=1;var ropeGO=new GameObject("Explicit fallback bungee visual — Rope Toolkit unavailable");ropeGO.transform.SetParent(root,false);b.rope=ropeGO.AddComponent<LineRenderer>();b.rope.sharedMaterial=ropeMaterial;b.rope.widthMultiplier=.13f;b.rope.numCapVertices=4;b.rope.numCornerVertices=3;b.rope.useWorldSpace=true;b.rope.positionCount=2;b.rope.SetPosition(0,b.craneAnchor.position);b.rope.SetPosition(1,b.truck.transform.position+Vector3.up*.5f);b.wind=root.gameObject.AddComponent<AudioSource>();b.wind.clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/WeatherMaker/Prefab/Sound/Weather/WeatherMakerWind1.ogg");b.strain=root.gameObject.AddComponent<AudioSource>();b.strain.clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/NWH/Vehicle Physics 2/Sound/Transmission/TransmissionWhine.wav");b.strain.loop=true;b.strain.playOnAwake=false;b.strain.spatialBlend=0;b.wind.loop=true;b.wind.playOnAwake=false;b.wind.pitch=1;b.wind.spatialBlend=0;
 SportsEventAuthoring.Box("Concrete demolition bay foundation",new Vector3(4,-.5f,5),new Vector3(110,1,110),concrete,contact,root);for(int k=0;k<4;k++){float x=k<2?-18:-13,z=k%2==0?-17:-12;SportsEventAuthoring.Box("Lattice crane tower leg",new Vector3(x,32.5f,z),new Vector3(.8f,65,.8f),steel,contact,root);}for(int y=0;y<13;y++){for(int edge=0;edge<2;edge++){float side=edge==0?-1:1;SportsEventAuthoring.Box("Crane lattice transverse",new Vector3(-15.5f,y*5,-14.5f+side*2.5f),new Vector3(6,.18f,.18f),steel,null,root);SportsEventAuthoring.Box("Crane lattice longitudinal",new Vector3(-15.5f+side*2.5f,y*5,-14.5f),new Vector3(.18f,.18f,6),steel,null,root);var a=SportsEventAuthoring.Box("Crane lattice diagonal",new Vector3(-15.5f+side*2.5f,y*5+2.5f,-14.5f),new Vector3(.18f,7,.18f),steel,null,root);a.transform.localRotation=Quaternion.Euler(y%2==0?45:-45,0,0);var bdiag=SportsEventAuthoring.Box("Crane lattice diagonal",new Vector3(-15.5f,y*5+2.5f,-14.5f+side*2.5f),new Vector3(.18f,7,.18f),steel,null,root);bdiag.transform.localRotation=Quaternion.Euler(0,0,y%2==0?45:-45);}}SportsEventAuthoring.Box("Crane jib",new Vector3(-8,65,-12),new Vector3(22,1.2f,1.2f),steel,contact,root);CombineCrane(root,steel);foreach(int side in new[]{-1,1}){SportsRallyAuthoring.Prop(root,"Assets/ShipContainerPack/URP/Prefabs/ShipContainerBlue_URP.prefab",new Vector3(side*32,0,32),new Vector3(5,3,11));SportsRallyAuthoring.Prop(root,"Assets/ScaffoldsPack/URP/Prefabs/SM_RollingScaffold.prefab",new Vector3(side*34,0,-28),new Vector3(4,7,4));}var sign=SportsEventAuthoring.Label("Bay sports signage","BUNGEE DEMOLITION  /  BAY "+(i+1),root.position+new Vector3(0,4,-38),.2f,m.setup.players[i].color);sign.transform.SetParent(root,true);
 foreach(int side in new[]{-1,1})for(int k=0;k<12;k++)SportsRallyAuthoring.Prop(root,"Assets/RoadPropsPack/URP/Prefabs/RoadBlock02_URP.prefab",new Vector3(-45+k*8,0,side*47),new Vector3(5,1.2f,.7f));var dustPrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CoreCollapse/Demo/Prefabs/Particles/Dust.prefab");var dust=UnityEngine.Object.Instantiate(dustPrefab,root);dust.name="Pooled vendor demolition dust";foreach(var script in dust.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(script);b.dust=dust.GetComponentInChildren<ParticleSystem>();var main=b.dust.main;main.playOnAwake=false;main.loop=false;main.maxParticles=256;main.simulationSpace=ParticleSystemSimulationSpace.World;var emission=b.dust.emission;emission.rateOverTime=0;emission.SetBursts(Array.Empty<ParticleSystem.Burst>());b.dust.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);m.bays[i]=b;m.playerViews[i]=SportsEventAuthoring.Camera("Bungee player "+(i+1));m.playerViews[i].view.farClipPlane=140;SportsRallyAuthoring.TuneCamera(m.playerViews[i]);m.playerViews[i].view.enabled=i==0;}
 var surround=SportsEventAuthoring.Mat(Folder,"Industrial yard surround",new Color(.24f,.28f,.29f),.12f);surround.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/NWH/Common/Textures/Ground/AsphaltAlbedo.png");surround.mainTextureScale=new Vector2(140,65);SportsEventAuthoring.Box("Continuous industrial venue ground",new Vector3(300,-.8f,0),new Vector3(950,.3f,360),surround,contact);m.broadcast=SportsEventAuthoring.Camera("Demolition broadcast");m.broadcast.view.farClipPlane=2000;m.broadcast.view.enabled=false;m.broadcast.Pose(new Vector3(12,28,10),new Vector3(-28,20,-54),68,true);m.cameras=new[]{m.playerViews[0].view};SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);var skip=m.menus.replayButtons[3];for(int k=0;k<3;k++)UnityEngine.Object.DestroyImmediate(m.menus.replayButtons[k]);m.menus.replayButtons=new[]{skip};var skipCaption=skip.GetComponent<Michsky.UI.Heat.ButtonManager>();skipCaption.buttonText="SKIP FINALE";skipCaption.normalTextObj.text="SKIP FINALE";skip.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,-430);Preview(m);SportsEventAuthoring.Save(Folder);Validate();}
 static GameObject Tower(){var root=new GameObject("Ten-storey Core-Collapse modular tower");var columnDebris=Fragments("Prefractured structural column",new Vector3(.8f,4.5f,.8f));var floorDebris=Fragments("Prefractured floor slab",new Vector3(11,.38f,11));var supports=new Support[10,5];var pieces=new BungeeModule[10,5];for(int level=0;level<10;level++){for(int c=0;c<4;c++){var p=new Vector3(c%2==0?-4.6f:4.6f,2.3f+level*4.8f,c<2?-4.6f:4.6f);pieces[level,c]=Module(root.transform,"Load bearing column "+level+" / "+c,p,new Vector3(.8f,4.6f,.8f),columnDebris,55,25,level);supports[level,c]=pieces[level,c].GetComponent<Support>();}pieces[level,4]=Module(root.transform,"Floor diaphragm "+level,new Vector3(0,4.7f+level*4.8f,0),new Vector3(11,.38f,11),floorDebris,85,35,level);supports[level,4]=pieces[level,4].GetComponent<Support>();var slab=pieces[level,4].transform;for(int side=-1;side<=1;side+=2){for(int k=0;k<4;k++){SportsEventAuthoring.Box("Inset window glazing",new Vector3(-3.6f+k*2.4f,-1.5f,side*4.9f),new Vector3(2.1f,2.6f,.07f),glass,null,slab);SportsEventAuthoring.Box("Facade sill beam",new Vector3(-3.6f+k*2.4f,-2.9f,side*4.9f),new Vector3(2.35f,.16f,.3f),concrete,null,slab);}}}
 for(int level=0;level<10;level++)for(int c=0;c<5;c++){var support=supports[level,c];var so=new SerializedObject(support);so.FindProperty("supportCapacity").floatValue=c==4?4:1;so.FindProperty("supportWeight").floatValue=c==4?2.5f:1;var references=c==4?Enumerable.Range(0,4).Select(k=>supports[level,k]).ToArray():level==0?Array.Empty<Support>():new[]{supports[level-1,4]};var array=so.FindProperty("supportedBy");array.arraySize=references.Length;for(int k=0;k<references.Length;k++)array.GetArrayElementAtIndex(k).objectReferenceValue=references[k];so.ApplyModifiedPropertiesWithoutUndo();var field=typeof(Support).GetField("onCollapse",BindingFlags.Instance|BindingFlags.NonPublic);var ev=(Support.OnCollapseEvent)field.GetValue(support);if(ev==null){ev=new Support.OnCollapseEvent();field.SetValue(support,ev);}UnityEventTools.AddPersistentListener(ev,pieces[level,c].Collapsed);EditorUtility.SetDirty(support);}
 var prefab=PrefabUtility.SaveAsPrefabAsset(root,"Assets/"+Folder+"/Prefabs/Ten Storey Destructible Tower.prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;}
 static BungeeModule Module(Transform parent,string name,Vector3 p,Vector3 size,GameObject fragments,float hp,int budget,int level){var root=new GameObject(name);root.transform.SetParent(parent,false);root.transform.localPosition=p;var support=root.AddComponent<Support>();var core=root.AddComponent<CollapserPrefrag>();var m=root.AddComponent<BungeeModule>();m.core=core;m.level=level;m.budget=budget;var coreSO=new SerializedObject(core);coreSO.FindProperty("startingHp").floatValue=hp;coreSO.FindProperty("collapsedPrefab").objectReferenceValue=fragments;coreSO.ApplyModifiedPropertiesWithoutUndo();var mf=wall.GetComponentInChildren<MeshFilter>();var model=new GameObject("Core-Collapse concrete architectural module");model.transform.SetParent(root.transform,false);model.AddComponent<MeshFilter>().sharedMesh=mf.sharedMesh;model.AddComponent<MeshRenderer>().sharedMaterial=concrete;var bounds=mf.sharedMesh.bounds;model.transform.localScale=new Vector3(size.x/bounds.size.x,size.y/bounds.size.y,size.z/bounds.size.z);model.transform.localPosition=-Vector3.Scale(bounds.center,model.transform.localScale);var collider=root.AddComponent<BoxCollider>();collider.size=size;collider.sharedMaterial=contact;return m;}
 static GameObject Fragments(string name,Vector3 size){var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CoreCollapse/Demo/Prefabs/PreFrag/Wall-Frag.prefab");var meshes=source.GetComponentsInChildren<MeshFilter>();Bounds bounds=new Bounds();bool first=true;foreach(var f in meshes){var r=f.GetComponent<Renderer>();if(first){bounds=r.bounds;first=false;}else bounds.Encapsulate(r.bounds);}var scale=new Vector3(size.x/bounds.size.x,size.y/bounds.size.y,size.z/bounds.size.z);var root=new GameObject(name);root.AddComponent<BungeeDebris>();for(int side=0;side<2;side++){var half=new GameObject("Physical fracture cluster "+side);half.transform.SetParent(root.transform,false);foreach(var f in meshes){if((f.GetComponent<Renderer>().bounds.center.x<bounds.center.x?0:1)!=side)continue;var model=new GameObject(f.name);model.transform.SetParent(half.transform,false);model.transform.localPosition=Vector3.Scale(f.transform.position-bounds.center,scale);model.transform.localRotation=f.transform.rotation;model.transform.localScale=Vector3.Scale(f.transform.lossyScale,scale);model.AddComponent<MeshFilter>().sharedMesh=f.sharedMesh;model.AddComponent<MeshRenderer>().sharedMaterial=concrete;}if(size.y<1){for(int front=-1;front<=1;front+=2)for(int k=0;k<2;k++){float x=(side==0?-1:1)*(1.2f+k*2.4f);SportsEventAuthoring.Box("Falling facade glazing",new Vector3(x,-1.5f,front*4.9f),new Vector3(2.1f,2.6f,.07f),glass,null,half.transform);SportsEventAuthoring.Box("Falling facade sill",new Vector3(x,-2.9f,front*4.9f),new Vector3(2.35f,.16f,.3f),concrete,null,half.transform);}}var renderers=half.GetComponentsInChildren<Renderer>();if(renderers.Length==0){UnityEngine.Object.DestroyImmediate(half);continue;}var rb=half.AddComponent<Rigidbody>();rb.mass=3;rb.solverIterations=8;Bounds hb=renderers[0].bounds;foreach(var r in renderers)hb.Encapsulate(r.bounds);var collider=half.AddComponent<BoxCollider>();collider.center=half.transform.InverseTransformPoint(hb.center);collider.size=hb.size;collider.sharedMaterial=contact;}var prefab=PrefabUtility.SaveAsPrefabAsset(root,"Assets/"+Folder+"/Prefabs/"+name+".prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;}
 static void CombineCrane(Transform root,Material material){var parts=root.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("Crane lattice")||f.name=="Lattice crane tower leg"||f.name=="Crane jib").ToArray();var data=parts.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=root.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray();var mesh=new Mesh{name="Modeled lattice crane"};mesh.CombineMeshes(data,true,true);string path="Assets/"+Folder+"/Models/Lattice Crane.asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved==null){AssetDatabase.CreateAsset(mesh,path);saved=mesh;}else{saved.Clear();saved.vertices=mesh.vertices;saved.normals=mesh.normals;saved.uv=mesh.uv;saved.triangles=mesh.triangles;saved.RecalculateBounds();saved.UploadMeshData(false);EditorUtility.SetDirty(saved);UnityEngine.Object.DestroyImmediate(mesh);}foreach(var f in parts){var renderer=f.GetComponent<Renderer>();if(f.GetComponent<Collider>()==null)UnityEngine.Object.DestroyImmediate(f.gameObject);else{UnityEngine.Object.DestroyImmediate(renderer);UnityEngine.Object.DestroyImmediate(f);}}var g=new GameObject("Persistent modeled lattice crane");g.transform.SetParent(root,false);g.AddComponent<MeshFilter>().sharedMesh=saved;g.AddComponent<MeshRenderer>().sharedMaterial=material;}
 static void Preview(BungeeMatch m){var tower=(GameObject)PrefabUtility.InstantiatePrefab(m.bays[0].towerPrefab);tower.transform.position=m.bays[0].towerMount.position;var camera=m.broadcast.view;var previous=camera.targetTexture;var rect=camera.rect;var active=RenderTexture.active;var rt=new RenderTexture(512,288,24);rt.Create();camera.targetTexture=rt;camera.rect=new Rect(0,0,1,1);m.broadcast.Pose(new Vector3(1,32,-3),new Vector3(-55,30,-100),62,true);camera.Render();RenderTexture.active=rt;var image=new Texture2D(512,288,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,512,288),0,0);image.Apply();string path="Assets/"+Folder+"/Art/Menu Preview.png";File.WriteAllBytes(path,image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);camera.targetTexture=previous;camera.rect=rect;RenderTexture.active=active;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tower);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.mipmapEnabled=false;importer.SaveAndReimport();}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<BungeeMatch>();if(m==null&&!EditorApplication.isPlaying){EditorSceneManager.OpenScene(Scene);m=UnityEngine.Object.FindAnyObjectByType<BungeeMatch>();}if(m==null||m.bays.Length!=4)throw new Exception("Four demolition bays required");foreach(var b in m.bays){if(b.spring==null||b.rope==null||b.truck==null||b.towerPrefab==null)throw new Exception("Bungee references missing");var modules=b.towerPrefab.GetComponentsInChildren<BungeeModule>();if(modules.Length!=50||modules.Any(x=>x.core==null||x.GetComponent<Support>()==null))throw new Exception("Expected 50 vendor-supported structural modules per tower");}BungeeExpansionAuthoring.Validate(m);Debug.Log("BUNGEE_SAVED_SCENE_VALIDATED 4 bays / 50 modules each / explicit Rope Toolkit fallback");}
